const DEFINITION = Symbol.for("@cloudflare/config:definition");
/**
* Unwrap an authored config from its value / promise / function shape, awaiting
* the result. A function config is invoked with {@link ConfigContext}.
*/
async function unwrap(config, ctx) {
	return typeof config === "function" ? await config(ctx) : await config;
}
